--======================================================================================================================================

-- SELECT 'VALIDAR SE TODOS OS FUNCS POSSUEM HISTORICO DE SALARIO ATUALIZADO' AS INFORMACAO;

-- WITH DADOS AS (
--     SELECT 
--         *,
--         DENSE_RANK() OVER (
--             PARTITION BY CODCOLIGADA,
--                          CHAPA
--             ORDER BY CODCOLIGADA ASC, 
--                      CHAPA ASC, 
--                      CONVERT(
--                         DATE,
--                         CONCAT(
--                         RIGHT(LEFT([Data de mudança (ddmmaaaa hh:mm:ss)], 8), 4),
--                         SUBSTRING(LEFT([Data de mudança (ddmmaaaa hh:mm:ss)],8), 3, 2),
--                         LEFT(LEFT([Data de mudança (ddmmaaaa hh:mm:ss)], 8), 2)
--                         ),
--                     112
--                 ) DESC 
--         ) AS ORDEM
--     FROM ZMIGRA_PFHSTSAL
-- ),
-- DADOS2 AS (
--     SELECT * FROM DADOS WHERE ORDEM = 1
-- ),
-- DADOS3 AS (
--     SELECT
--         PFUNC.CODCOLIGADA AS COLIGADA,
--         PFUNC.CHAPA AS MATRICULA,
--         PFUNC.[Data de Admissão] AS DTADMISSAO,
--         PFUNC.[Salário (Formato 999999999999,99)] AS SALARIO,
--         HIST.[Data de mudança (ddmmaaaa hh:mm:ss)] AS DATA_MUDANCA,
--         HIST.[Valor atual do salário] AS SALARIO_HISTORICO
--     FROM ZMIGRA_PFUNC PFUNC
--     LEFT JOIN DADOS2 HIST
--     ON HIST.CODCOLIGADA = PFUNC.CODCOLIGADA
--     AND HIST.Chapa = PFUNC.CHAPA
--     AND HIST.[Valor atual do salário] = PFUNC.[Salário (Formato 999999999999,99)]
-- )
-- SELECT 
--     DADOS3.*,
--     (
--         SELECT TOP 1 
--             CONVERT(
--                 DATE,
--                 CONCAT(
--                 RIGHT(LEFT([Data de mudança (ddmmaaaa hh:mm:ss)], 8), 4),
--                 SUBSTRING(LEFT([Data de mudança (ddmmaaaa hh:mm:ss)],8), 3, 2),
--                 LEFT(LEFT([Data de mudança (ddmmaaaa hh:mm:ss)], 8), 2)
--                 ),
--                 112
--             ) 
--         FROM DADOS2 
--         WHERE DADOS2.CODCOLIGADA = DADOS3.COLIGADA 
--           AND DADOS2.CHAPA = DADOS3.MATRICULA
--     ) AS ULT_DTMUDANCA,
--     (
--         SELECT TOP 1 [Valor atual do salário] 
--         FROM DADOS2 
--         WHERE DADOS2.CODCOLIGADA = DADOS3.COLIGADA 
--           AND DADOS2.CHAPA = DADOS3.MATRICULA
--     ) 
--     AS ULT_SAL_HST
-- FROM DADOS3 
-- WHERE SALARIO_HISTORICO IS NULL 
--   OR SALARIO <> SALARIO_HISTORICO
-- ORDER BY 1, 2